import{_ as e}from"./chunks/setting.COWnsdkD.js";import{_ as a,o,c as r,a3 as i}from"./chunks/framework.BM_-pWjS.js";const m=JSON.parse('{"title":"Rating propagation","description":"","frontmatter":{},"headers":[],"relativePath":"en/rating-spec.md","filePath":"en/rating-spec.md"}'),n={name:"en/rating-spec.md"};function s(h,t,p,d,l,g){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="rating-propagation" tabindex="-1">Rating propagation <a class="header-anchor" href="#rating-propagation" aria-label="Permalink to &quot;Rating propagation&quot;">​</a></h1><p>When you rate a grouped photo, the rating propagates to every photo in the group.</p><h2 id="default-behavior" tabindex="-1">Default behavior <a class="header-anchor" href="#default-behavior" aria-label="Permalink to &quot;Default behavior&quot;">​</a></h2><p>Rating the representative shot of a group in the thumbnail grid writes the same star rating and color label to all shots in that group. This is the default behavior — designed to simplify the common workflow of accepting or rejecting a burst or bracket sequence as a whole.</p><h2 id="individual-adjustments" tabindex="-1">Individual adjustments <a class="header-anchor" href="#individual-adjustments" aria-label="Permalink to &quot;Individual adjustments&quot;">​</a></h2><p>After a group-wide rating, you can override the rating for individual shots from the <strong>metadata bar</strong>.</p><ol><li>Select the representative shot of the group.</li><li>The metadata bar shows a list of all shots in the group.</li><li>Select the shot you want to change in the metadata bar and apply a new rating.</li></ol><p>Ratings applied from the metadata bar are written only to the selected shot and do not affect other shots in the group.</p><h2 id="customizing-propagation" tabindex="-1">Customizing propagation <a class="header-anchor" href="#customizing-propagation" aria-label="Permalink to &quot;Customizing propagation&quot;">​</a></h2><p>You can change cross-type propagation behavior in the <strong>Rating Propagation</strong> section of Settings.</p><p><img src="'+e+'" alt="Settings - Rating Propagation"></p><p>Each <strong>row</strong> is the source type you rated; each <strong>column</strong> is a type that receives the same rating. Checkmarks are fixed (a type always writes to itself); toggles let you enable or disable propagation between different types.</p><h2 id="when-propagation-happens" tabindex="-1">When propagation happens <a class="header-anchor" href="#when-propagation-happens" aria-label="Permalink to &quot;When propagation happens&quot;">​</a></h2><p>Propagation is written immediately when you apply the rating. To undo, press <code>⌘Z</code>.</p><h2 id="where-xmp-is-written" tabindex="-1">Where XMP is written <a class="header-anchor" href="#where-xmp-is-written" aria-label="Permalink to &quot;Where XMP is written&quot;">​</a></h2><p>The write destination for each shot in the group follows the same rules as regular ratings.</p><table tabindex="0"><thead><tr><th>File type</th><th>Saved to</th></tr></thead><tbody><tr><td>RAW (<code>.arw</code>, <code>.cr3</code>, etc.)</td><td>Sidecar <code>.xmp</code> file with the same stem name</td></tr><tr><td>JPEG</td><td>Embedded directly in the file</td></tr></tbody></table>',17)])])}const f=a(n,[["render",s]]);export{m as __pageData,f as default};
